BEGIN;
CREATE TABLE governance.risks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, domain text NOT NULL, subject_type text NOT NULL, subject_id uuid, title text NOT NULL, level governance.risk_level NOT NULL, status text NOT NULL DEFAULT 'OPEN', owner_user_id uuid REFERENCES identity.users(id), review_at timestamptz);
CREATE TABLE governance.controls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, control_code text NOT NULL, title text NOT NULL, description text NOT NULL, owner_user_id uuid REFERENCES identity.users(id), status text NOT NULL DEFAULT 'PLANNED', UNIQUE(tenant_id,control_code));
CREATE TABLE governance.control_evidence (control_id uuid NOT NULL REFERENCES governance.controls(id) ON DELETE CASCADE, evidence_id uuid NOT NULL, linked_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(control_id,evidence_id));
CREATE TABLE governance.incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, category text NOT NULL, severity governance.risk_level NOT NULL, status text NOT NULL DEFAULT 'OPEN', description text NOT NULL, detected_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE governance.human_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, subject_type text NOT NULL, subject_id uuid NOT NULL, reviewer_user_id uuid NOT NULL REFERENCES identity.users(id), status governance.review_status NOT NULL DEFAULT 'OPEN', rationale text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
COMMIT;
